{
  "title": "Does checkout button B really sell more?",
  "setting": "Monday at Nook & Needle",
  "mission": "You're the junior marketing analyst at an online craft store. Decide whether button B's lead is real or just luck, and make **a launch recommendation the test can actually support**.",
  "deadline": "Launch review with {{product}} today at 3 p.m.; the big email goes out tomorrow",
  "panels": [
    {
      "title": "Early checkout button test",
      "metrics": [
        {
          "label": "Button A purchases",
          "value": "8.0%",
          "note": "32 purchases in 400 visits"
        },
        {
          "label": "Button B purchases",
          "value": "10.0%",
          "note": "40 purchases in 400 visits"
        },
        {
          "label": "Gap (B − A)",
          "value": "+2.0 points",
          "note": "10.0% − 8.0%; not yet checked for luck"
        }
      ],
      "note": "First 24 hours · 400 visits per version · visitors split randomly 50/50"
    }
  ],
  "team": [
    {
      "id": "product",
      "role": "Product manager",
      "expertise": "Owns the email launch and wants a timely decision the team can defend.",
      "ai": false
    },
    {
      "id": "data",
      "role": "Data scientist",
      "expertise": "Knows experiment design, hypothesis tests and how sample size affects what a test can detect.",
      "ai": false
    },
    {
      "id": "ai",
      "role": "AI analysis assistant",
      "expertise": "Runs test calculations, sample-size estimates and tracking checks when asked.",
      "ai": true
    }
  ],
  "meters": [
    {
      "id": "risk",
      "label": "Risk of a wrong launch call",
      "start": 50,
      "goodWhen": "low"
    },
    {
      "id": "trust",
      "label": "{{product}}'s trust",
      "start": 60,
      "goodWhen": "high"
    },
    {
      "id": "delay",
      "label": "Launch delay",
      "start": 10,
      "goodWhen": "low"
    }
  ],
  "skills": [
    {
      "id": "chance",
      "name": "Real difference or chance?",
      "practice": "Write one sentence explaining why 4 purchases in 50 visits versus 6 in 50 does not, by itself, prove that one version is better."
    },
    {
      "id": "sample",
      "name": "Choose a sample size",
      "practice": "Ask an AI or sample-size calculator for the visits per version needed to detect 8% versus 10%, with a 5% cutoff and 80% detection chance; check that it gives roughly 3,300."
    },
    {
      "id": "explain",
      "name": "Explain a test result",
      "practice": "Explain the full result—8.0% for A, 10.0% for B and p = 0.0045—to a nontechnical colleague in two plain sentences."
    }
  ],
  "startNodeId": "start",
  "nodes": [
    {
      "id": "start",
      "messages": [
        {
          "from": "product",
          "text": "The big email goes out tomorrow. B is at 10.0% versus 8.0% for A—a 2-percentage-point gap, or 25% above A's rate—so I'd like to launch it at today's review."
        },
        {
          "from": "data",
          "text": "One day is a small look. A hypothesis test checks whether a gap this size could happen by random luck; we need that check before calling B better."
        }
      ],
      "prompt": "What do you do before the 3 p.m. review?",
      "choices": [
        {
          "id": "check",
          "text": "Ask {{ai}} for a hypothesis test before I recommend either button.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "If the buttons were equally good, a gap at least this big would appear about 32 times in 100. That probability is called a p-value; here p = 0.32."
            },
            {
              "from": "data",
              "text": "Our cutoff is 5 in 100, so this doesn't clear it. That doesn't prove the buttons are equal; today's data just can't tell them apart."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -20
            },
            {
              "meter": "trust",
              "change": 5
            },
            {
              "meter": "delay",
              "change": 5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "good",
              "text": "You tested whether the early gap could be chance instead of treating the higher percentage as a winner.",
              "example": null
            }
          ],
          "next": "sample"
        },
        {
          "id": "ship",
          "text": "Back B for tomorrow's launch; 10.0% is already 25% higher than 8.0%.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "That works for my timeline. Give me one careful sentence for the launch note."
            },
            {
              "from": "data",
              "text": "Shipping B doesn't settle whether the gap was luck. The launch can be a business trade-off, but the test still can't tell the buttons apart."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 25
            },
            {
              "meter": "trust",
              "change": 5
            },
            {
              "meter": "delay",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "improve",
              "text": "You used the early gap as if it were a settled result. The 25% calculation was right, but 400 visits per version could not rule out chance.",
              "example": "\"B is ahead, but 400 visits per version is not enough to rule out chance yet.\""
            }
          ],
          "next": "early"
        },
        {
          "id": "wait",
          "text": "Keep the test until Friday and look at the percentages again then.",
          "quality": "fair",
          "replies": [
            {
              "from": "data",
              "text": "Waiting is safer than launching on today's numbers, but Friday is a date, not a sample size. We need to know how many visits the question requires."
            },
            {
              "from": "product",
              "text": "I can discuss a delay if you bring me a firm plan at 3 p.m."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -5
            },
            {
              "meter": "trust",
              "change": -5
            },
            {
              "meter": "delay",
              "change": 15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "You avoided an instant launch, but an arbitrary end date can still leave too little data to answer the question.",
              "example": "Set the visit target first, then turn it into a finish date."
            }
          ],
          "next": "sample"
        }
      ]
    },
    {
      "id": "early",
      "messages": [
        {
          "from": "product",
          "text": "B is going live for tomorrow's email traffic. What should my launch note say about the test?"
        },
        {
          "from": "data",
          "text": "You can make a speed-first business call, but the statistical result is still uncertain. Please keep those two things separate."
        }
      ],
      "prompt": "What do you write for the launch note?",
      "choices": [
        {
          "id": "honest-note",
          "text": "Write: 'B is ahead so far, but the gap could be chance. We're choosing speed, not claiming a proven win.'",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "Thanks. I can defend a fast business decision as long as we don't disguise it as a settled result."
            },
            {
              "from": "data",
              "text": "Exactly. Launching early is a trade-off; claiming certainty would be a misreading of the test."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -10
            },
            {
              "meter": "trust",
              "change": 10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "good",
              "text": "You separated the business decision to move fast from the statistical conclusion, which was still uncertain. That let {{product}} act without spreading a false claim.",
              "example": null
            }
          ],
          "next": "early-cautious"
        },
        {
          "id": "sure-note",
          "text": "Write: 'B is proven to lift purchases by 25%, so this is a clear win for tomorrow's launch.'",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "That's a strong claim. I'll use it unless {{data}} objects."
            },
            {
              "from": "data",
              "text": "I do. The relative lift is 25% in this sample, but the test hasn't ruled out luck. Correct that before the note goes wider."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 15
            },
            {
              "meter": "trust",
              "change": -20
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "improve",
              "text": "The 25% calculation was right, but 'proven' was not. You turned an early sample into a promise the test could not support.",
              "example": "\"B's early rate was 25% higher than A's, but the gap could still be chance.\""
            }
          ],
          "next": "rushed"
        }
      ]
    },
    {
      "id": "sample",
      "messages": [
        {
          "from": "data",
          "text": "Sample size means how many visits we compare. To have an 80% chance of catching a real move from 8.0% to 10.0% with our 5-in-100 cutoff, we need about 3,300 visits per version. Smaller samples can miss a gain that size."
        },
        {
          "from": "ai",
          "text": "At the current traffic, Friday would bring about 2,000 visits per version. Reaching 3,300 would take about eight more days; I can also check that the split stays random and purchase tracking stays unchanged."
        },
        {
          "from": "product",
          "text": "Missing tomorrow's email costs us a useful launch window. But I don't want to call a lucky result a win, either."
        }
      ],
      "prompt": "What plan do you take to the launch review?",
      "choices": [
        {
          "id": "full-sample",
          "text": "Keep the 50/50 test until 3,300 visits per version and move B's launch past tomorrow's email.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "I don't love the delay, but now I understand the trade-off. I'll hold B's launch and use your reason in the update."
            },
            {
              "from": "ai",
              "text": "I'll stop at the planned target, not keep peeking for a moment we like. The random split and tracking checks passed."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -25
            },
            {
              "meter": "trust",
              "change": -5
            },
            {
              "meter": "delay",
              "change": 35
            }
          ],
          "timeJump": {
            "label": "Eight days later",
            "panel": {
              "title": "Completed checkout button test",
              "metrics": [
                {
                  "label": "Button A purchases",
                  "value": "8.0%",
                  "note": "264 purchases in 3,300 visits"
                },
                {
                  "label": "Button B purchases",
                  "value": "10.0%",
                  "note": "330 purchases in 3,300 visits"
                },
                {
                  "label": "Gap (B − A)",
                  "value": "+2.0 points",
                  "note": "Also 25% above A's purchase rate"
                },
                {
                  "label": "p-value",
                  "value": "0.0045",
                  "note": "Below the 0.05 cutoff"
                }
              ],
              "note": "3,300 visits per version · random split and tracking checks passed"
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "good",
              "text": "You set the finish line from the sample-size calculation, not from when you hoped to be done. You also accepted a real launch delay as the cost of a clearer answer.",
              "example": null
            },
            {
              "skill": "explain",
              "kind": "good",
              "text": "You gave {{product}} a plain reason for the delay, so waiting didn't sound like a reflex to collect more data.",
              "example": "\"We need 3,300 visits per version to have a good chance of detecting a real 2-point gain; today's test is too small.\""
            }
          ],
          "next": "final"
        },
        {
          "id": "friday-stop",
          "text": "Stop Friday at about 2,000 visits per version and make the launch call with whatever we have.",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "That protects part of my timeline. Just be honest if Friday's result still leaves us uncertain."
            },
            {
              "from": "ai",
              "text": "I'll run the numbers Friday. With a smaller sample, even a real 2-point gain may not cross our cutoff."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 5
            },
            {
              "meter": "trust",
              "change": 5
            },
            {
              "meter": "delay",
              "change": 20
            }
          ],
          "timeJump": {
            "label": "Friday afternoon",
            "panel": {
              "title": "Friday checkout button test",
              "metrics": [
                {
                  "label": "Button A purchases",
                  "value": "8.0%",
                  "note": "160 purchases in 2,000 visits"
                },
                {
                  "label": "Button B purchases",
                  "value": "9.4%",
                  "note": "188 purchases in 2,000 visits"
                },
                {
                  "label": "Gap (B − A)",
                  "value": "+1.4 points",
                  "note": "9.4% − 8.0%; still not enough to rule out luck"
                },
                {
                  "label": "p-value",
                  "value": "0.12",
                  "note": "Above the 0.05 cutoff"
                }
              ],
              "note": "2,000 visits per version · stopped at the planned date"
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "You picked a faster compromise, but the sample was still short of what the 8% to 10% question needed. Saving time could leave the team without an answer.",
              "example": null
            }
          ],
          "next": "friday"
        }
      ]
    },
    {
      "id": "friday",
      "messages": [
        {
          "from": "ai",
          "text": "The hypothesis test gives p = 0.12: if the buttons were equally good, a gap at least this big would appear about 12 times in 100. That doesn't clear our 5-in-100 cutoff."
        },
        {
          "from": "data",
          "text": "This is not proof that B does nothing. Our Friday sample was too small to answer the question reliably."
        },
        {
          "from": "product",
          "text": "I've already moved the launch once. I need either a careful next step or a recommendation I can defend."
        }
      ],
      "prompt": "What do you do with Friday's result?",
      "choices": [
        {
          "id": "finish-sample",
          "text": "Continue to 3,300 visits per version, and tell {{product}} the extra delay buys a real answer.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "That's another delay, but at least it finishes the question. Keep the explanation that plain in your report."
            },
            {
              "from": "ai",
              "text": "I'll return to the original target and record Friday's check. The conclusion will come from the completed sample, not from picking the best-looking day."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -20
            },
            {
              "meter": "trust",
              "change": -5
            },
            {
              "meter": "delay",
              "change": 20
            }
          ],
          "timeJump": {
            "label": "Four days later",
            "panel": {
              "title": "Completed checkout button test",
              "metrics": [
                {
                  "label": "Button A purchases",
                  "value": "8.0%",
                  "note": "264 purchases in 3,300 visits"
                },
                {
                  "label": "Button B purchases",
                  "value": "10.0%",
                  "note": "330 purchases in 3,300 visits"
                },
                {
                  "label": "Gap (B − A)",
                  "value": "+2.0 points",
                  "note": "Also 25% above A's purchase rate"
                },
                {
                  "label": "p-value",
                  "value": "0.0045",
                  "note": "Below the 0.05 cutoff"
                }
              ],
              "note": "3,300 visits per version · random split and tracking checks passed"
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "good",
              "text": "You didn't treat an unclear result as proof of no difference. You finished the number of visits the original question needed.",
              "example": null
            }
          ],
          "next": "final"
        },
        {
          "id": "uncertain-stop",
          "text": "Stop here and report B as promising but unproven, with no launch recommendation based on this test.",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "Understood. I'll hold the launch claim, and we'll decide separately whether another test is worth the time."
            },
            {
              "from": "data",
              "text": "That's the honest reading. Just don't describe the result as evidence that the buttons are the same."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -10
            },
            {
              "meter": "trust",
              "change": 5
            },
            {
              "meter": "delay",
              "change": 5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "good",
              "text": "You communicated uncertainty instead of forcing a winner from a sample that was too small.",
              "example": null
            },
            {
              "skill": "sample",
              "kind": "improve",
              "text": "A stronger plan would have set the needed visit count before Friday, so the team didn't spend a week and still lack an answer.",
              "example": "Set 3,300 visits per version as the finish line before choosing a stop date."
            }
          ],
          "next": "inconclusive"
        },
        {
          "id": "launch-friday",
          "text": "Recommend B now because it has stayed ahead, and avoid another delay.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "I'll prepare the launch, but I need the claim to match the evidence."
            },
            {
              "from": "data",
              "text": "B staying ahead isn't enough. At p = 0.12, chance is still a reasonable explanation, so we can't call this a proven win."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 25
            },
            {
              "meter": "trust",
              "change": -10
            },
            {
              "meter": "delay",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "improve",
              "text": "Staying ahead at every look does not rule out luck. Friday's p = 0.12 meant the test still could not support a proven-win claim.",
              "example": "\"B still looks promising, but chance could explain this gap; we need more visits or an uncertain decision.\""
            }
          ],
          "next": "rushed"
        }
      ]
    },
    {
      "id": "final",
      "messages": [
        {
          "from": "ai",
          "text": "At 3,300 visits per version, A had 264 purchases and B had 330. The test gives p = 0.0045, below our 0.05 cutoff, so this 2-point gap would be very unlikely if the buttons were equally good."
        },
        {
          "from": "data",
          "text": "That doesn't guarantee B will lift every future week by exactly 25%. It supports launching B, with normal monitoring after launch."
        },
        {
          "from": "product",
          "text": "Please skip the statistical shorthand. What happened, what do you recommend, and how sure are we?"
        }
      ],
      "prompt": "What do you tell {{product}}?",
      "choices": [
        {
          "id": "plain-report",
          "text": "Say: 'B reached 10.0% versus 8.0%. Luck is now unlikely, so let's launch B and keep monitoring it.'",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "That's clear: a 2-point gain in the test, strong evidence it wasn't just luck, and a follow-up after launch. I'll approve the launch."
            },
            {
              "from": "data",
              "text": "You also kept the claim tied to what we measured. That's the right scope."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -10
            },
            {
              "meter": "trust",
              "change": 15
            },
            {
              "meter": "delay",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "good",
              "text": "You led with the rates people care about, then said what the test ruled out and what to do next. No statistical shorthand was needed.",
              "example": null
            },
            {
              "skill": "chance",
              "kind": "good",
              "text": "You called chance unlikely rather than claiming certainty, and you kept monitoring after launch.",
              "example": null
            }
          ],
          "next": "launch-full"
        },
        {
          "id": "p-only",
          "text": "Send only: 'p = 0.0045. B wins. Launch it.'",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "I'll approve B, but that number doesn't tell the rest of the team what happened. Please put the size and meaning in plain words next time."
            },
            {
              "from": "ai",
              "text": "A plain version is: 'Purchases were 10.0% with B and 8.0% with A, and chance is now unlikely to explain the gap.'"
            }
          ],
          "effects": [
            {
              "meter": "trust",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "improve",
              "text": "The statistics were right, but 'p = 0.0045' did not tell {{product}} what happened or why it mattered.",
              "example": "\"B reached 10.0% versus 8.0% for A. Chance is now unlikely to explain the gap, so we should launch and monitor it.\""
            }
          ],
          "next": "launch-full"
        },
        {
          "id": "promise",
          "text": "Say: 'B is guaranteed to keep purchases 25% higher every week, so we can launch and stop measuring.'",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "I'm comfortable launching, not with a guarantee. I'll approve the launch with a post-launch check, and the note will describe only this test."
            },
            {
              "from": "data",
              "text": "The evidence is strong, but no single test promises the same lift forever."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 10
            },
            {
              "meter": "trust",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "improve",
              "text": "Strong evidence is not a guarantee that every future week will match the test. The 25% figure describes this sample.",
              "example": "\"The test supports launching B, and we'll check whether the gain holds after launch.\""
            }
          ],
          "next": "launch-full"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "early-cautious",
      "outcome": "B went live for tomorrow's email traffic with an honest note: 10.0% versus 8.0% was an early gap, not a proven lift. The team recorded the launch as a speed-versus-certainty trade-off."
    },
    {
      "id": "rushed",
      "outcome": "B's launch went ahead before the evidence could rule out chance. {{data}} stopped the team from presenting it as a proven win, so the launch note had to be rewritten around the uncertainty."
    },
    {
      "id": "inconclusive",
      "outcome": "Friday's test ended at 8.0% for A and 9.4% for B. The team reported a promising but uncertain gap and did not use the test to justify a launch; 2,000 visits per version was still short of the target."
    },
    {
      "id": "launch-full",
      "outcome": "B launched after the full test: purchases were 8.0% with A and 10.0% with B, a 2.0-percentage-point gain, or 25% more purchases per visit. The team kept monitoring instead of treating that lift as a guarantee."
    }
  ],
  "summary": [
    "A higher percentage in a small sample is a lead, not proof; a hypothesis test asks whether chance could explain the gap.",
    "Choose the sample size from the difference you want to detect, then set the calendar; stopping at a convenient date can leave the question unanswered.",
    "Explain the size of the result, what uncertainty remains and the recommended action without hiding behind a p-value."
  ]
}

{
  "title": "E se a luz chegasse em pacotinhos?",
  "setting": "Uma tarde no quintal-laboratório",
  "mission": "Você encontrou uma caixa de luz com frestas e uma tela muito sensível. **Decida o que testar para descobrir como a energia da luz chega** e o que o desenho final revela.",
  "deadline": null,
  "panels": [
    {
      "title": "Caixa de luz do quintal",
      "metrics": [
        {
          "label": "Cor da luz",
          "value": "Sempre a mesma",
          "note": "Para comparar os testes sem trocar a cor"
        },
